function externalSearchPayload(form){return{externalAction:'search',query:value(form,'query'),provider:value(form,'provider')||'all',category:value(form,'category'),marketType:value(form,'marketType'),searchIn:value(form,'searchIn')||'both',status:value(form,'status')||'open',closeDays:numberValue(form,'closeDays'),closeAfter:isoValue(form,'closeAfter'),closeBefore:isoValue(form,'closeBefore'),exactPhrase:checked(form,'exactPhrase'),sort:value(form,'sort')||'relevance'};}function validateExternalSearchResponse(res){if(!res||!Array.isArray(res.events))throw new Error('External market search is unavailable on the current backend deployment.');return res;}
